private val integerToken = Regex("-?(0|[1-9][0-9]*)")
private val numberToken = Regex("-?(0|[1-9][0-9]*)([.][0-9]+)?([eE][+-]?[0-9]+)?")
private val literalStops = setOf(' ', '\t', '\r', '\n', '{', '}', '[', ']', ':', ',', '"')
private const val MAX_NESTING = 35 // open brackets at once: the nesting limit of the Python codec's raw pre-scan
private const val MAX_INTEGER_DIGITS = 4300 // the digits Python's int() accepts by default

private fun requireStrict(descriptor: SerialDescriptor, element: JsonElement, bounds: WireInteger?, path: String) {
    if (element is JsonNull) throw SerializationException("$path: null is not allowed")
    when (descriptor.kind) {
        PrimitiveKind.LONG -> requireInteger(element, bounds, path)
        PrimitiveKind.BOOLEAN -> requireBoolean(element, path)
        StructureKind.CLASS -> (element as? JsonObject)?.forEach { (key, value) ->
            requireProperty(descriptor, key, value, path)
        }
        StructureKind.LIST -> (element as? JsonArray)?.forEachIndexed { index, item ->
            requireStrict(descriptor.getElementDescriptor(0), item, bounds, "$path[$index]")
        }
        else -> Unit
    }
}

private fun requireProperty(owner: SerialDescriptor, key: String, value: JsonElement, path: String) {
    val index = owner.getElementIndex(key)
    if (index == CompositeDecoder.UNKNOWN_NAME) return
    val bounds = owner.getElementAnnotations(index).filterIsInstance<WireInteger>().firstOrNull()
    requireStrict(owner.getElementDescriptor(index), value, bounds, "$path.$key")
}

private fun requireInteger(element: JsonElement, bounds: WireInteger?, path: String) {
    val token = (element as? JsonPrimitive)?.takeIf { !it.isString && integerToken.matches(it.content) }
    val number = token?.content?.toLongOrNull() ?: throw SerializationException("$path: expected a JSON integer")
    if (number < (bounds?.minimum ?: Long.MIN_VALUE) || number > (bounds?.maximum ?: Long.MAX_VALUE)) {
        throw SerializationException("$path: integer outside its bounds")
    }
}

private fun requireBoolean(element: JsonElement, path: String) {
    val literal = element as? JsonPrimitive
    if (literal == null || literal.isString || (literal.content != "true" && literal.content != "false")) {
        throw SerializationException("$path: expected a JSON boolean")
    }
}

private fun scanRawText(text: String) {
    val open = ArrayDeque<MutableSet<String>?>() // per open bracket: the keys of an object so far, null for an array
    var at = 0
    while (at < text.length) {
        val char = text[at]
        at = when (char) {
            '{', '[' -> {
                open.addLast(if (char == '{') HashSet() else null)
                if (open.size > MAX_NESTING) throw notJson("nesting deeper than $MAX_NESTING levels")
                at
            }
            '}', ']' -> {
                open.removeLastOrNull()
                at
            }
            '"' -> scanString(text, at, open.lastOrNull())
            ' ', '\t', '\r', '\n', ':', ',' -> at
            else -> scanLiteral(text, at)
        } + 1
    }
}

private fun notJson(why: String) = SerializationException("the frame is not valid JSON: $why")

private fun scanString(text: String, start: Int, keys: MutableSet<String>?): Int {
    val end = stringEnd(text, start)
    if (end >= text.length) return end // unterminated: the parser fails
    if (keys != null && nextCharAfterSpace(text, end + 1) == ':' && !keys.add(keyText(text, start, end))) {
        throw SerializationException("duplicate key in the frame")
    }
    return end
}

private fun stringEnd(text: String, start: Int): Int {
    var at = start + 1
    while (at < text.length && text[at] != '"') {
        if (text[at] < ' ') throw notJson("control character in a string")
        at += if (text[at] == '\\') 2 else 1
    }
    return at
}

private fun scanLiteral(text: String, start: Int): Int {
    var end = start
    while (end < text.length && text[end] !in literalStops) end++
    if (!isJsonLiteral(text.substring(start, end))) {
        throw notJson("a bare value that is not true, false, null or a number")
    }
    return end - 1
}

private fun isJsonLiteral(literal: String): Boolean = when {
    literal == "true" || literal == "false" || literal == "null" -> true
    !numberToken.matches(literal) -> false
    literal.any { it == '.' || it == 'e' || it == 'E' } -> literal.toDouble().isFinite()
    else -> literal.removePrefix("-").length <= MAX_INTEGER_DIGITS
}

private fun nextCharAfterSpace(text: String, from: Int): Char? {
    var at = from
    while (at < text.length && text[at] in " \t\r\n") at++
    return text.getOrNull(at)
}

private fun keyText(text: String, start: Int, end: Int): String {
    val quoted = text.substring(start, end + 1)
    if ('\\' !in quoted) return quoted.substring(1, quoted.length - 1)
    return (Json.parseToJsonElement(quoted) as JsonPrimitive).content
}

